#a11y-toggle {
  position: fixed;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2000;
  width: 48px;
  height: 48px;
  border: none;
  border-radius: 8px 0 0 8px;
  background: #0d6efd;
  color: #fff;
  font-size: 1.4rem;
  cursor: pointer;
}

#a11y-panel {
  position: fixed;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  z-index: 1999;
  width: 280px;
  max-height: 80vh;
  overflow-y: auto;
  background: #fff;
  box-shadow: -2px 0 12px rgba(0, 0, 0, .25);
  padding: 16px;
  border-radius: 8px 0 0 8px;
}

.a11y-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 12px;
}

.a11y-option {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 10px 4px;
  border: 1px solid #ccc;
  border-radius: 6px;
  background: #f8f9fa;
  cursor: pointer;
  font-size: .8rem;
}

.a11y-option.active {
  background: #0d6efd;
  color: #fff;
  border-color: #0d6efd;
}

.a11y-fontsize {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}

#a11y-reset {
  width: 100%;
  padding: 8px;
  border: none;
  border-radius: 6px;
  background: #dc3545;
  color: #fff;
  cursor: pointer;
}

/* ---- Wirkungen der Einstellungen ---- */
html.a11y-contrast body {
  filter: contrast(1.4);
}
html.a11y-invert body {
  filter: invert(1) hue-rotate(180deg);
}
html.a11y-grayscale body {
  filter: grayscale(1);
}
html.a11y-underline-links a {
  text-decoration: underline !important;
}
html.a11y-readable-font body {
  font-family: Arial, Helvetica, sans-serif !important;
}
html.a11y-pause-animations * {
  animation: none !important;
  transition: none !important;
}
html.a11y-big-cursor,
html.a11y-big-cursor * {
  cursor: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="32" height="32"><path d="M0 0 L0 24 L8 18 L12 28 L16 26 L12 16 L22 16 Z" fill="black" stroke="white"/></svg>') 0 0, auto !important;
}
html {
  font-size: calc(16px * var(--a11y-font-scale, 1));
}
