&lt;script&gt;
// accessibility-widget.js
(function () {
  const STORAGE_KEY = 'a11yWidgetSettings';

  const defaultSettings = {
    contrast: false,
    invert: false,
    grayscale: false,
    fontSize: 0,       // in Stufen, z.B. -2 .. +4
    underlineLinks: false,
    readableFont: false,
    pauseAnimations: false,
    bigCursor: false,
  };

  let settings = loadSettings();
  let speaking = false;

  function loadSettings() {
    try {
      const stored = JSON.parse(localStorage.getItem(STORAGE_KEY));
      return Object.assign({}, defaultSettings, stored || {});
    } catch (e) {
      return Object.assign({}, defaultSettings);
    }
  }

  function saveSettings() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  }

  function applySettings() {
    const root = document.documentElement;
    root.classList.toggle('a11y-contrast', settings.contrast);
    root.classList.toggle('a11y-invert', settings.invert);
    root.classList.toggle('a11y-grayscale', settings.grayscale);
    root.classList.toggle('a11y-underline-links', settings.underlineLinks);
    root.classList.toggle('a11y-readable-font', settings.readableFont);
    root.classList.toggle('a11y-pause-animations', settings.pauseAnimations);
    root.classList.toggle('a11y-big-cursor', settings.bigCursor);
    root.style.setProperty('--a11y-font-scale', `${1 + settings.fontSize * 0.1}`);
  }

  function resetSettings() {
    settings = Object.assign({}, defaultSettings);
    saveSettings();
    applySettings();
    syncControls();
  }

  // ---- Vorlesen (Web Speech API) ----
  function readPage() {
    if (!('speechSynthesis' in window)) {
      alert('Vorlesen wird von diesem Browser nicht unterstützt.');
      return;
    }
    if (speaking) {
      window.speechSynthesis.cancel();
      speaking = false;
      updateReadButton();
      return;
    }
    const main = document.querySelector('main, .container-fluid, body');
    const text = main ? main.innerText : document.body.innerText;
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = document.documentElement.lang || 'de-DE';
    utterance.onend = () =&gt; {
      speaking = false;
      updateReadButton();
    };
    window.speechSynthesis.speak(utterance);
    speaking = true;
    updateReadButton();
  }

  function updateReadButton() {
    const btn = document.getElementById('a11y-read-toggle');
    if (btn) btn.classList.toggle('active', speaking);
  }

  // ---- UI Aufbau ----
  function buildWidget() {
    const toggle = document.createElement('button');
    toggle.id = 'a11y-toggle';
    toggle.setAttribute('aria-label', 'Barrierefreiheit-Einstellungen öffnen');
    toggle.setAttribute('aria-expanded', 'false');
    toggle.innerHTML = '&lt;i class="fa-solid fa-universal-access" aria-hidden="true"&gt;&lt;/i&gt;';

    const panel = document.createElement('div');
    panel.id = 'a11y-panel';
    panel.setAttribute('role', 'dialog');
    panel.setAttribute('aria-label', 'Barrierefreiheit-Einstellungen');
    panel.hidden = true;

    panel.innerHTML = `
      &lt;h2 class="a11y-title"&gt;Barrierefreiheit&lt;/h2&gt;
      &lt;div class="a11y-grid"&gt;
        ${optionButton('contrast', 'fa-circle-half-stroke', 'Kontrast erhöhen')}
        ${optionButton('invert', 'fa-droplet', 'Farben invertieren')}
        ${optionButton('grayscale', 'fa-eye-slash', 'Graustufen')}
        ${optionButton('underlineLinks', 'fa-link', 'Links unterstreichen')}
        ${optionButton('readableFont', 'fa-font', 'Lesbare Schrift')}
        ${optionButton('pauseAnimations', 'fa-pause', 'Animationen stoppen')}
        ${optionButton('bigCursor', 'fa-arrow-pointer', 'Großer Cursor')}
        &lt;button type="button" id="a11y-read-toggle" class="a11y-option"&gt;
          &lt;i class="fa-solid fa-volume-high" aria-hidden="true"&gt;&lt;/i&gt;
          &lt;span&gt;Vorlesen&lt;/span&gt;
        &lt;/button&gt;
      &lt;/div&gt;
      &lt;div class="a11y-fontsize"&gt;
        &lt;span&gt;Textgröße&lt;/span&gt;
        &lt;button type="button" id="a11y-font-minus" aria-label="Schrift verkleinern"&gt;A-&lt;/button&gt;
        &lt;button type="button" id="a11y-font-plus" aria-label="Schrift vergrößern"&gt;A+&lt;/button&gt;
      &lt;/div&gt;
      &lt;button type="button" id="a11y-reset"&gt;Zurücksetzen&lt;/button&gt;
    `;

    document.body.appendChild(toggle);
    document.body.appendChild(panel);

    toggle.addEventListener('click', () =&gt; {
      const isOpen = panel.hidden === false;
      panel.hidden = isOpen;
      toggle.setAttribute('aria-expanded', String(!isOpen));
    });

    panel.querySelectorAll('[data-setting]').forEach((btn) =&gt; {
      btn.addEventListener('click', () =&gt; {
        const key = btn.dataset.setting;
        settings[key] = !settings[key];
        saveSettings();
        applySettings();
        syncControls();
      });
    });

    document.getElementById('a11y-read-toggle').addEventListener('click', readPage);
    document.getElementById('a11y-font-minus').addEventListener('click', () =&gt; changeFontSize(-1));
    document.getElementById('a11y-font-plus').addEventListener('click', () =&gt; changeFontSize(1));
    document.getElementById('a11y-reset').addEventListener('click', resetSettings);

    document.addEventListener('click', (e) =&gt; {
      if (!panel.hidden &amp;&amp; !panel.contains(e.target) &amp;&amp; e.target !== toggle) {
        panel.hidden = true;
        toggle.setAttribute('aria-expanded', 'false');
      }
    });

    syncControls();
  }

  function optionButton(key, icon, label) {
    return `
      &lt;button type="button" class="a11y-option" data-setting="${key}"&gt;
        &lt;i class="fa-solid ${icon}" aria-hidden="true"&gt;&lt;/i&gt;
        &lt;span&gt;${label}&lt;/span&gt;
      &lt;/button&gt;`;
  }

  function changeFontSize(delta) {
    settings.fontSize = Math.max(-2, Math.min(6, settings.fontSize + delta));
    saveSettings();
    applySettings();
  }

  function syncControls() {
    document.querySelectorAll('[data-setting]').forEach((btn) =&gt; {
      const key = btn.dataset.setting;
      btn.classList.toggle('active', !!settings[key]);
      btn.setAttribute('aria-pressed', String(!!settings[key]));
    });
  }

  document.addEventListener('DOMContentLoaded', () =&gt; {
    buildWidget();
    applySettings();
  });
})();
