  function updateReadButton() {
    const btn = document.getElementById('a11y-read-toggle');
    if (btn) btn.classList.toggle('active', speaking);
  }

  // Inline-SVG-Icons statt FontAwesome, damit sie unabhängig von der Seite funktionieren
  const icons = {
    access: '<svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor"><circle cx="12" cy="4" r="2"/><path d="M12 7c-4 0-7 1-7 3v2h4v9h2v-6h2v6h2v-9h4V10c0-2-3-3-7-3z"/></svg>',
