Und ergänze/ersetze die Funktionen `changeFontSize` und `syncControls`, damit der Prozentwert mit angezeigt wird:

```javascript
  function changeFontSize(delta) {
    settings.fontSize = Math.max(-2, Math.min(6, settings.fontSize + delta));
    saveSettings();
    applySettings();
    updateFontValue();
  }

  function updateFontValue() {
    const el = document.getElementById('a11y-font-value');
    if (el) el.textContent = Math.round((1 + settings.fontSize * 0.1) * 100) + '%';
