response.value:
Wichtiger Hinweis vorab: Es gibt **keine standardisierte, browserübergreifende JavaScript-API**, mit der eine Webseite die eingebaute Übersetzungsfunktion des Browsers direkt ansteuern kann. Nur Chrome bietet aktuell experimentell eine `Translator`-API (Built-in-AI, ab Chrome 138+, teils hinter einem Flag/Origin-Trial) an. Ich baue den Button daher so, dass er:

1. die experimentelle Chrome-`Translator`-API nutzt, wenn verfügbar (übersetzt den sichtbaren Text direkt auf der Seite),
2. andernfalls auf Google Translate als Fallback-Link ausweicht (funktioniert in jedem Browser).

**Ergänzung für das JavaScript** – neues Icon, neuer Button im Panel, neue Funktion:

```javascript
// Icon ergänzen (in das bestehende icons-Objekt einfügen)
icons.translate = '<svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor"><path d="M12.9 17.1l-1.4-1.4L13 14l-2-2 1.4-1.4 2 2 1.5-1.5 1.4 1.4-1.5 1.5 2 2-1.4 1.4-2-2-1.1 1.1zM3 5h7V3H3v2zm0 4h5V7H3v2zm11-6v2h3.5L12 10.5 13.5 12 18 7.5V11h2V3h-6z"/></svg>';
```

```javascript
// im panel.innerHTML ergänzen, z.B. nach dem a11y-fontsize-Block
<div class="a11y-translate">
  <button type="button" id="a11y-translate-toggle" class="a11y-translate__btn">
    ${icons.translate}
    <span id="a11y-translate-label">Seite auf Englisch anzeigen</span>
  </button>
</div>
```

```javascript
// neue Funktion + Event-Listener ergänzen
let translated = false;
let translating = false;
const originalTextNodes = new Map();

function collectTextNodes(root) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      if (!node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
      const tag = node.parentElement && node.parentElement.tagName;
      if (!tag || ['SCRIPT', 'STYLE', 'NOSCRIPT'].includes(tag)) return NodeFilter.FILTER_REJECT;
      if (node.parentElement.closest('#a11y-panel, #a11y-toggle')) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  const nodes = [];
  let n;
  while ((n = walker.nextNode())) nodes.push(n);
  return nodes;
}

async function translatePage() {
  const btn = document.getElementById('a11y-translate-toggle');
  const label = document.getElementById('a11y-translate-label');
  if (translating) return;

  // Übersetzung zurücksetzen
  if (translated) {
    originalTextNodes.forEach((text, node) => { node.nodeValue = text; });
    originalTextNodes.clear();
    translated = false;
    label.textContent = 'Seite auf Englisch anzeigen';
    return;
  }

  // Experimentelle Chrome Translator API (Built-in AI)
  if ('Translator' in self) {
    try {
      translating = true;
      label.textContent = 'Übersetze …';
      btn.disabled = true;

      const availability = await self.Translator.availability({
        sourceLanguage: document.documentElement.lang || 'de',
        targetLanguage: 'en',
      });
      if (availability === 'unavailable') throw new Error('Translator nicht verfügbar');

      const translator = await self.Translator.create({
        sourceLanguage: document.documentElement.lang || 'de',
        targetLanguage: 'en',
      });

      const nodes = collectTextNodes(document.body);
      for (const node of nodes) {
        originalTextNodes.set(node, node.nodeValue);
        try {
          node.nodeValue = await translator.translate(node.nodeValue);
        } catch (e) {
          // einzelnen Knoten überspringen, Rest weiter übersetzen
        }
      }

      translated = true;
      label.textContent = 'Original wiederherstellen';
    } catch (err) {
      console.warn('Translator API nicht nutzbar, Fallback auf Google Translate', err);
      openGoogleTranslateFallback();
      label.textContent = 'Seite auf Englisch anzeigen';
    } finally {
      translating = false;
      btn.disabled = false;
    }
  } else {
    openGoogleTranslateFallback();
  }
}

function openGoogleTranslateFallback() {
  const url = 'https://translate.google.com/translate?sl=auto&tl=en&u=' + encodeURIComponent(location.href);
  window.open(url, '_blank', 'noopener,noreferrer');
}
```

