  const STORAGE_KEY = 'a11yWidgetSettings';
  // Eigener Server-Endpunkt, der die Anfrage sicher an DeepL weiterleitet (Key bleibt serverseitig)
  const DEEPL_PROXY_URL = '/api/translate-proxy/';

