    const nodes = [];
    let n;
    while ((n = walker.nextNode())) nodes.push(n);
    return nodes;
  }

  // Textknoten + Originaltext einmalig zwischenspeichern, damit jede Sprachumschaltung vom deutschen Original ausgeht
  function ensureTextNodesCache() {
    if (!textNodesCache) {
      textNodesCache = collectTextNodes(document.body).map((node) => ({ node, original: node.nodeValue }));
    }
  }

  function restoreOriginal() {
    if (textNodesCache) {
      textNodesCache.forEach((item) => { item.node.nodeValue = item.original; });
    }
    currentLanguage = 'de';
  }

  async function translateViaBuiltInApi(targetLang) {
    const availability = await self.Translator.availability({
      sourceLanguage: 'de',
      targetLanguage: targetLang,
    });
    if (availability === 'unavailable') throw new Error('Translator API nicht verfügbar');

    const translator = await self.Translator.create({ sourceLanguage: 'de', targetLanguage: targetLang });
    for (const item of textNodesCache) {
      try {
        item.node.nodeValue = await translator.translate(item.original);
      } catch (e) {
        // einzelnen Knoten überspringen, Rest weiter übersetzen
      }
    }
  }

