  async function translateViaDeepLProxy(targetLang) {
    const texts = textNodesCache.map((item) => item.original);
    const response = await fetch(DEEPL_PROXY_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ texts, target_lang: targetLang.toUpperCase() }),
    });
    if (!response.ok) throw new Error('DeepL-Proxy-Anfrage fehlgeschlagen');
    const data = await response.json();
    const translations = data.translations || [];
    textNodesCache.forEach((item, i) => {
      if (translations[i]) item.node.nodeValue = translations[i];
    });
