        deepl_response = requests.post(
            settings.DEEPL_API_URL,
            data={
                'auth_key': settings.DEEPL_API_KEY,
                'text': texts,
                'target_lang': target_lang,
            },
            timeout=10,
        )
        deepl_response.raise_for_status()
        data = deepl_response.json()
    except requests.RequestException:
        return JsonResponse({'error': 'DeepL-Anfrage fehlgeschlagen'}, status=502)

    translations = [item['text'] for item in data.get('translations', [])]
    return JsonResponse({'translations': translations})
